	// UnitAll queries all units of measure
	UnitAll(context.Context, *QueryAllUnitRequest) (*QueryAllUnitResponse, error)
	// Account queries an account by ID
	Account(context.Context, *QueryGetAccountRequest) (*QueryGetAccountResponse, error)
	// AccountAll queries all accounts
	AccountAll(context.Context, *QueryAllAccountRequest) (*QueryAllAccountResponse, error)
	// JournalEntry queries a journal entry by ID
