	// JournalEntryAll queries all journal entries
	JournalEntryAll(context.Context, *QueryAllJournalEntryRequest) (*QueryAllJournalEntryResponse, error)
	// TrialBalance returns the trial balance (akuntansi)
	TrialBalance(context.Context, *QueryTrialBalanceRequest) (*QueryTrialBalanceResponse, error)
	// IncomeStatement returns the income statement / laba rugi (akuntansi)
	IncomeStatement(context.Context, *QueryIncomeStatementRequest) (*QueryIncomeStatementResponse, error)
	// BalanceSheet returns the balance sheet / neraca (akuntansi)
